#include <iostream>
#include <string>
#include "Board.h"
#include "eval/handcrafted_eval.h"
#include "eval/morphy_eval.h"
using namespace opera;
class Probe : public eval::HandcraftedEvaluator {
public:
 void show(const Board& board) {
  EvaluationTerms t;
  int base=evaluate_with_terms(board,board.getSideToMove(),t,true);
  eval::MorphyEvaluator morphy;
  std::cout << "{\"base_cp\":" << base << ",\"morphy_cp\":" << morphy.evaluate(board,board.getSideToMove())
   << ",\"phase\":" << t.phase << ",\"material_cp\":" << t.material[WHITE]-t.material[BLACK]
   << ",\"king_safety\":[" << t.king_safety[WHITE] << ',' << t.king_safety[BLACK]
   << "],\"mobility\":[" << t.mobility[WHITE] << ',' << t.mobility[BLACK]
   << "],\"development\":[" << t.development[WHITE] << ',' << t.development[BLACK] << "]}" << std::endl;
 }
};
int main() { std::string fen; Probe probe; while(std::getline(std::cin,fen)) { Board board(fen); probe.show(board); } }
